-- ==============================================================================
-- Migración 0092: contenido de la ficha de hotel en la base
-- La ficha componía en el navegador habitaciones, piscinas, restaurantes, bares, vida nocturna,
-- spa, políticas, preguntas frecuentes, pasadía y política de niños (los mismos textos de
-- ejemplo para todos los hoteles). Se guardan en cada hotel como punto de partida para que el
-- panel los muestre y cada propietario los corrija; la ficha ya los lee de aquí.
-- Generada por scripts/gen-hotel-details-seed.cjs. Sólo rellena lo vacío (extras: no pisa claves existentes).
-- ==============================================================================

UPDATE hotels SET
  room_types = CASE WHEN (room_types IS NULL OR room_types IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '[{"id":"deluxe","name":"Habitación Deluxe Garden View","size":"42 m²","view":"Vista a Jardines Tropicales","bed":"1 Cama King o 2 Queen","capacity":"2-3 Adultos","amenities":["A/C Climatizado","Smart TV 55\"","Minibar Incluido","WiFi 6","Balcón Privado","Cafetera Nespresso"],"price":650,"breakfast":true,"image":null,"description":"Elegante habitación con mobiliario contemporáneo en maderas nobles, terraza privada amueblada y baño de mármol con ducha tipo lluvia."},{"id":"ocean-suite","name":"Master Suite Frente al Mar","size":"68 m²","view":"Vista Frontal al Mar Caribe","bed":"1 Cama King Plush","capacity":"2 Adultos","amenities":["Vista Mar Directa","Bañera de Hidromasaje","Minibar Premium","Room Service 24h","Terraza con Camastros"],"price":1008,"breakfast":true,"image":null,"description":"Amplia suite con salón independiente, balcón panorámico con vistas directas al mar turquesa y amenidades de baño de diseñador."},{"id":"presidential-villa","name":"Villa Presidencial con Piscina Privada","size":"140 m²","view":"Vista Panorámica al Océano","bed":"2 Camas King + Sala","capacity":"4-5 Personas","amenities":["Piscina Infinity Privada","Mayordomo (Butler) 24h","Bar Abierto de Lujo","Parrilla BBQ","Acceso VIP"],"price":1820,"breakfast":true,"image":null,"description":"Máxima exclusividad caribeña: residencia de doble nivel con piscina plunge privada, comedor exterior y servicio de mayordomo personalizado."}]'::jsonb ELSE room_types END,
  pools = CASE WHEN (pools IS NULL OR pools IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '[{"name":"Piscina Infinity Panorámica Oceanfront","type":"Frente al Mar","depth":"1.20m - 1.60m","features":"Efecto infinito sobre el Mar Caribe, camas balinesas sumergidas y servicio de toallas premium.","vibe":"Vistas & Relajación"},{"name":"Piscina Laguna Central con Bar Acuático","type":"Piscina Central","depth":"1.40m","features":"Swim-up wet bar, hidromasaje integrado y actividades de aquagym diurnas.","vibe":"Animación & Cócteles"},{"name":"Piscina Oasis ''Solo Adultos'' (Zen Pool)","type":"Solo Adultos","depth":"1.30m","features":"Ambiente de máxima serenidad, tumbonas acolchadas privadas y menú de aguas aromatizadas.","vibe":"Tranquilidad Total"},{"name":"Parque Acuático Splash con Toboganes","type":"Familiar & Niños","depth":"0.30m - 0.60m","features":"Toboganes acuáticos, juegos interactivos de agua y socorristas certificados.","vibe":"Diversión Familiar"},{"name":"Piscina de Hidroterapia & Jacuzzis","type":"Spa & Termal","depth":"1.00m","features":"Cuellos de cisne, cascadas de agua tibia e hidrojets para relajación muscular profunda.","vibe":"Bienestar Terapéutico"}]'::jsonb ELSE pools END,
  dining = CASE WHEN (dining IS NULL OR dining IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '[{"name":"El Palmar Buffet Internacional & Show Cooking","cuisine":"Internacional & Caribeña","hours":"07:00 - 11:00 / 12:30 - 16:00 / 18:30 - 22:30","description":"Estaciones gourmet en vivo con cortes a la parrilla, pastas frescas, mariscos locales, panadería artesanal y opciones sin gluten.","dressCode":"Casual","reservations":false,"tag":"Buffet Todo Incluido"},{"name":"La Cava de Autor","cuisine":"Fusión Mediterránea & Alta Cocina","hours":"18:30 - 23:00","description":"Propuesta de alta cocina con maridajes guiados por sommelier y una selecta bodega de más de 300 etiquetas de vino.","dressCode":"Elegante / Smart Casual","reservations":true,"tag":"Cena a la Carta"},{"name":"Breeze Beach Club & Raw Bar","cuisine":"Mariscos, Ceviches & Grill de Playa","hours":"11:00 - 18:30","description":"Ubicado directamente sobre la arena: langosta a la brasa, tiraditos, aguachiles y cócteles tropicales con vista al mar.","dressCode":"Casual de Playa","reservations":false,"tag":"Frente al Mar"},{"name":"Samurai Teppanyaki & Sushi Bar","cuisine":"Cocina Japonesa & Asiática","hours":"18:30 - 22:30","description":"Mesas teppanyaki interactivas con show cooking de chefs, rollos de autor, tempuras y gyozas al vapor.","dressCode":"Casual Elegante","reservations":true,"tag":"Especialidad Asiática"},{"name":"Trattoria Bella Italia","cuisine":"Cocina Italiana Tradicional","hours":"18:30 - 22:30","description":"Pizzas al horno de leña, risottos cremosos, carpaccios y pastas frescas con salsas tradicionales italianas.","dressCode":"Casual","reservations":false,"tag":"Italiano"},{"name":"Fuego Criollo Dominican Grill","cuisine":"Gastronomía Dominicana Contemporánea","hours":"19:00 - 23:00","description":"Sabores auténticos de la isla reinterpretados: chivo liniero confitado, sancocho de mariscos y mofongo gourmet.","dressCode":"Casual Elegante","reservations":true,"tag":"Sabores Locales"}]'::jsonb ELSE dining END,
  bars_lounges = CASE WHEN (bars_lounges IS NULL OR bars_lounges IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '[{"name":"Sky Lounge & Cocktail Rooftop","type":"Mixología en Azotea","hours":"17:00 - 01:00","description":"Terraza panorámica con vistas al atardecer, cócteles de autor con rones añejos dominicanos y música chillout.","specialty":"Ron Punch Infusionado & Mamajuana Signature"},{"name":"Swim-up Oasis Wet Bar","type":"Bar Acuático en Piscina","hours":"10:00 - 18:00","description":"Bebidas heladas, frappés naturales, cervezas locales y piñas coladas servidas dentro de la piscina infinita.","specialty":"Piña Colada en Coco Natural"},{"name":"Lobby Bar & Rum Experience","type":"Lobby & Degustación","hours":"09:00 - 00:00","description":"Elegante salón central con piano en vivo y catas dirigidas de los mejores rones dominicanos.","specialty":"Old Fashioned con Ron Dominicano"},{"name":"Coco Beach Bar","type":"Bar de Playa","hours":"10:00 - 19:00","description":"Kiosco rústico en la arena sirviendo cocos fríos, mojitos de maracuyá y snacks ligeros.","specialty":"Coco Loco & Mojito Caribeño"},{"name":"Sports Bar & Lounge 24 Horas","type":"Sports Bar 24h","hours":"24 Horas (Todo Incluido)","description":"Retransmisión de partidos en vivo, mesas de billar y servicio ininterrumpido de snacks calientes.","specialty":"Cerveza Presidente Helada & Snacks"}]'::jsonb ELSE bars_lounges END,
  nightlife = CASE WHEN (nightlife IS NULL OR nightlife IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '[{"name":"Discoteca & Club ''Neon Caribe''","type":"Discoteca & Nightclub","hours":"22:30 - 03:00 AM","music":"DJ Set & Ritmos Latinos","description":"Sonido de alta fidelidad, iluminación robótica, DJs residentes, barra libre de cócteles premium y ritmos latinos e internacionales.","dressCode":"Elegante Casual (+18)"},{"name":"Teatro Principal & Gran Escenario","type":"Shows en Vivo & Musicales","hours":"21:00 - 22:30","music":"Orquesta en Vivo","description":"Producciones escénicas diarias, tributos musicales internacionales, ballet folclórico dominicano y noches de circo caribeño.","dressCode":"Casual"},{"name":"Fiestas Temáticas & Beach Party","type":"Fiestas en la Playa","hours":"Noches Semanales","music":"Merengue & Bachata","description":"Fogata en la arena, Fiesta Blanca (White Party), orquesta de merengue en directo y estaciones de comida nocturna.","dressCode":"White / Tropical"}]'::jsonb ELSE nightlife END,
  spa_info = CASE WHEN (spa_info IS NULL OR spa_info IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '{"name":"Amanera Spa","concept":"Santuario de hidroterapia y bienestar holístico caribeño","size":"1,800 m² de Instalaciones","hours":"08:00 AM - 20:00 PM","schedule":"08:00 AM - 20:00 PM","bookingPolicy":"Reservación recomendada en recepción del Spa","facilities":[{"name":"Circuito Hidrotermal","desc":"Piscina de contrastes frío/calor, cascadas cervicales y camas de hidromasaje."},{"name":"Sauna Finlandés & Baño de Vapor","desc":"Aromaterapia con eucalipto silvestre y cromoterapia relajante."},{"name":"Cabinas de Masaje frente al Mar","desc":"Palapas privadas sobre la arena con brisa marina y sonido de olas."},{"name":"Tratamientos Autóctonos","desc":"Envolturas corporales con cacao orgánico dominicano y sales minerales de Montecristi."},{"name":"Salón de Belleza & Estética","desc":"Manicura spa, peinados para ocasiones especiales y tratamientos faciales antiedad."}],"treatments":["Masaje Relajante Caribeño con Aceite de Coco Virgen (60/90 min)","Envoltura Desintoxicante con Cacao Dominicano y Miel Silvestre","Tratamiento Facial Antiedad con Perlas Marinas y Ácido Hialurónico","Exfoliación Corporal con Sales Minerales de Montecristi","Ritual en Pareja ''Atardecer Romántico'' con Aromaterapia y Cava"],"hydrotherapy":["Piscina Dinámica de Contrastes (Aguas Térmicas & Frías)","Cascadas Cervicales de Alta Presión y Cuellos de Cisne","Camas de Hidromasaje Sumergidas con Microburbujas","Sauna Finlandés a 85°C con Esencias de Eucalipto","Baño de Vapor Turco (Hammam) con Aromaterapia Relajante","Duchas de Sensaciones Bitérmicas y Pediluvio Terapéutico"]}'::jsonb ELSE spa_info END,
  policies = CASE WHEN (policies IS NULL OR policies IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '{"checkIn":"3:00 PM (15:00)","checkOut":"12:00 PM (Mediodía)","cancellation":"Cancelación 100% gratuita hasta 48 horas antes de la llegada.","children":"Familia amigable. Cunas disponibles bajo solicitud previa y acceso al club infantil.","pets":"Se admiten mascotas de hasta 10kg en habitaciones designadas (pueden aplicar cargos adicionales).","deposit":"Se requiere un depósito reembolsable en tarjeta de crédito al momento del check-in para gastos incidentales.","transfers":"Servicio de traslado privado aeropuerto-hotel disponible las 24 horas con reservación previa.","paymentMethods":["Visa","Mastercard","American Express","Apple Pay","Efectivo USD/DOP"]}'::jsonb ELSE policies END,
  faqs = CASE WHEN (faqs IS NULL OR faqs IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '[{"q":"¿A qué distancia está el hotel del aeropuerto más cercano?","a":"El alojamiento cuenta con servicio de transfer privado coordinable con anticipación. El tiempo estimado de traslado oscila entre 15 y 30 minutos dependiendo de la ubicación del destino."},{"q":"¿Qué incluye la tarifa de hospedaje?","a":"Todas las tarifas reservadas a través de nuestro portal incluyen desayuno gourmet diario, acceso a piscinas, Wi-Fi de alta velocidad en todo el complejo, toallas de playa y uso del gimnasio."},{"q":"¿Cuáles son las condiciones de cancelación?","a":"Ofrecemos cancelación sin penalidad hasta 48 horas antes del check-in. Para cancelaciones posteriores se cobrará la primera noche de estancia."},{"q":"¿Tienen opciones gastronómicas para dietas especiales?","a":"Sí, todos los restaurantes del complejo disponen de menús adaptados para comensales celíacos (sin gluten), vegetarianos, veganos o con alergias alimentarias señalizadas."}]'::jsonb ELSE faqs END,
  check_in_time = coalesce(check_in_time, '3:00 PM (15:00)'),
  check_out_time = coalesce(check_out_time, '12:00 PM (Mediodía)'),
  extras = '{"day_pass":{"price":"$85 USD (~RD$ 5,100) / persona","hours":"09:30 AM - 06:00 PM","includes":"Incluye acceso total a piscinas, playa privada, almuerzo buffet ilimitado, bebidas nacionales y toallas."},"kids_policy":{"title":"Hasta 2 Niños Gratis (0 - 5 años)","text":"Niños de 6 a 12 años con 50% de descuento compartiendo habitación. Acceso sin costo al Kids Club y parque acuático infantil."},"nightlife_summary":"Discoteca, Teatro & Shows","experience_tags":["Playa de Arena Blanca","Régimen Todo Incluido","Servicio de Mayordomo 24/7","Piscinas Climatizadas","Spa & Wellness de Autor","Deportes Acuáticos No Motorizados","Kids Club & Teens Lounge","WiFi de Alta Velocidad"]}'::jsonb || coalesce(extras, '{}'::jsonb)
WHERE slug = 'amanera-playa-grande';

