  policies = CASE WHEN (policies IS NULL OR policies IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '{"checkIn":"3:00 PM (15:00)","checkOut":"12:00 PM (Mediodía)","cancellation":"Cancelación 100% gratuita hasta 48 horas antes de la llegada.","children":"Familia amigable. Cunas disponibles bajo solicitud previa y acceso al club infantil.","pets":"Se admiten mascotas de hasta 10kg en habitaciones designadas (pueden aplicar cargos adicionales).","deposit":"Se requiere un depósito reembolsable en tarjeta de crédito al momento del check-in para gastos incidentales.","transfers":"Servicio de traslado privado aeropuerto-hotel disponible las 24 horas con reservación previa.","paymentMethods":["Visa","Mastercard","American Express","Apple Pay","Efectivo USD/DOP"]}'::jsonb ELSE policies END,
  faqs = CASE WHEN (faqs IS NULL OR faqs IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '[{"q":"¿A qué distancia está el hotel del aeropuerto más cercano?","a":"El alojamiento cuenta con servicio de transfer privado coordinable con anticipación. El tiempo estimado de traslado oscila entre 15 y 30 minutos dependiendo de la ubicación del destino."},{"q":"¿Qué incluye la tarifa de hospedaje?","a":"Todas las tarifas reservadas a través de nuestro portal incluyen desayuno gourmet diario, acceso a piscinas, Wi-Fi de alta velocidad en todo el complejo, toallas de playa y uso del gimnasio."},{"q":"¿Cuáles son las condiciones de cancelación?","a":"Ofrecemos cancelación sin penalidad hasta 48 horas antes del check-in. Para cancelaciones posteriores se cobrará la primera noche de estancia."},{"q":"¿Tienen opciones gastronómicas para dietas especiales?","a":"Sí, todos los restaurantes del complejo disponen de menús adaptados para comensales celíacos (sin gluten), vegetarianos, veganos o con alergias alimentarias señalizadas."}]'::jsonb ELSE faqs END,
  check_in_time = coalesce(check_in_time, '3:00 PM (15:00)'),
  check_out_time = coalesce(check_out_time, '12:00 PM (Mediodía)'),
  extras = '{"day_pass":{"price":"$85 USD (~RD$ 5,100) / persona","hours":"09:30 AM - 06:00 PM","includes":"Incluye acceso total a piscinas, playa privada, almuerzo buffet ilimitado, bebidas nacionales y toallas."},"kids_policy":{"title":"Hasta 2 Niños Gratis (0 - 5 años)","text":"Niños de 6 a 12 años con 50% de descuento compartiendo habitación. Acceso sin costo al Kids Club y parque acuático infantil."},"nightlife_summary":"Discoteca, Teatro & Shows","experience_tags":["Playa de Arena Blanca","Régimen Todo Incluido","Servicio de Mayordomo 24/7","Piscinas Climatizadas","Spa & Wellness de Autor","Deportes Acuáticos No Motorizados","Kids Club & Teens Lounge","WiFi de Alta Velocidad"]}'::jsonb || coalesce(extras, '{}'::jsonb)
