  room_types = CASE WHEN (room_types IS NULL OR room_types IN ('[]'::jsonb, '{}'::jsonb, 'null'::jsonb)) THEN '[{"id":"deluxe","name":"Habitación Deluxe Garden View","size":"42 m²","view":"Vista a Jardines Tropicales","bed":"1 Cama King o 2 Queen","capacity":"2-3 Adultos","amenities":["A/C Climatizado","Smart TV 55\"","Minibar Incluido","WiFi 6","Balcón Privado","Cafetera Nespresso"],"price":420,"breakfast":true,"image":null,"description":"Elegante habitación con mobiliario contemporáneo en maderas nobles, terraza privada amueblada y baño de mármol con ducha tipo lluvia."},{"id":"ocean-suite","name":"Master Suite Frente al Mar","size":"68 m²","view":"Vista Frontal al Mar Caribe","bed":"1 Cama King Plush","capacity":"2 Adultos","amenities":["Vista Mar Directa","Bañera de Hidromasaje","Minibar Premium","Room Service 24h","Terraza con Camastros"],"price":651,"breakfast":true,"image":null,"description":"Amplia suite con salón independiente, balcón panorámico con vistas directas al mar turquesa y amenidades de baño de diseñador."},{"id":"presidential-villa","name":"Villa Presidencial con Piscina Privada","size":"140 m²","view":"Vista Panorámica al Océano","bed":"2 Camas King + Sala","capacity":"4-5 Personas","amenities":["Piscina Infinity Privada","Mayordomo (Butler) 24h","Bar Abierto de Lujo","Parrilla BBQ","Acceso VIP"],"price":1176,"breakfast":true,"image":null,"description":"Máxima exclusividad caribeña: residencia de doble nivel con piscina plunge privada, comedor exterior y servicio de mayordomo personalizado."}]'::jsonb ELSE room_types END,
